module.exports = /*#__PURE__*/JSON.parse('{"Navigation":{"home":"Accueil","impressum":"Mentions Légales","privacy":"Politique de Confidentialité","contact":"Contact","language":"Langue","terms":"Conditions d\'Utilisation"},"Meta":{"title":"Wildscope : Application d\'Identification de la Faune et d\'Exploration de la Nature par IA","description":"Découvrez et identifiez la faune avec la technologie IA, explorez la nature avec des cartes hors ligne et suivez les animaux comme un pro. Votre compagnon ultime pour les aventures en pleine nature."},"Hero":{"title":"Identification de la Faune et Exploration de la Nature par IA","subtitle":"Identifiez instantanément les plantes et les animaux, suivez la faune avec précision et explorez la nature en toute confiance - même hors ligne. Votre compagnon outdoor complet alimenté par l\'IA avancée.","feature_1":"Reconnaissance et Suivi des Espèces par IA","feature_2":"Cartes Hors Ligne & Base de Données de la Faune","feature_3":"Quiz Interactifs sur la Nature & Apprentissage","feature_4":"Navigation GPS & Outils de Boussole","feature_5":"Mode Aventure Textuel","feature_6":"Communauté Mondiale de la Faune","appstore":"Télécharger sur l\'App Store","playstore":"Obtenir sur Google Play","download_subtext":"Rejoignez plus de 50 000 Passionnés de Nature"},"About":{"title":"Votre Guide Complet d\'Identification de la Faune et de la Nature","paragraph1":"Vivez la nature comme jamais auparavant avec la technologie IA avancée de Wildscope. Que vous identifiiez des plantes lors d\'une randonnée, suiviez la faune dans des zones reculées ou exploriez les écosystèmes locaux, nos fonctionnalités complètes fonctionnent parfaitement en ligne et hors ligne.","bullet1":"Identification instantanée par IA des plantes, animaux et champignons","bullet2":"Cartes détaillées hors ligne et guides des espèces pour chaque lieu","bullet3":"Apprentissage interactif via des quiz et le mode aventure","bullet4":"Navigation GPS et outils de suivi de la faune","bullet5":"Communauté mondiale de passionnés de nature","paragraph2":"Des promenades nature décontractées au suivi sérieux de la faune, Wildscope combine une technologie IA de pointe avec des outils outdoor complets pour enrichir chaque expérience nature."},"Features":{"title":"Outils Complets d\'Identification de la Faune et d\'Exploration de la Nature","feature1_title":"Reconnaissance Avancée de la Faune","feature1_desc":"Identifiez instantanément des milliers d\'espèces avec notre système de reconnaissance par IA. Obtenez des informations détaillées sur les animaux, les plantes et les champignons, y compris les comportements, les préférences d\'habitat et les variations saisonnières.","feature1_point1":"Identification des espèces en temps réel par IA","feature1_point2":"Base de données complète de la faune","feature1_point3":"Modèles de suivi saisonnier","feature2_title":"Cartes & Navigation Hors Ligne","feature2_desc":"Ne vous perdez plus jamais avec notre système complet de cartographie hors ligne. Téléchargez des cartes régionales et des données sur la faune pour une navigation et une identification fiables des espèces, même dans les zones reculées sans réseau mobile.","feature2_point1":"Téléchargement de cartes pour utilisation hors ligne","feature2_point2":"Suivi GPS et points de repère","feature2_point3":"Outils d\'analyse du terrain","feature3_title":"Apprentissage Interactif","feature3_desc":"Apprenez sur la nature à travers des quiz captivants, des défis et notre mode aventure textuel unique. Testez vos connaissances, améliorez vos compétences outdoor et découvrez de nouvelles espèces dans votre région.","feature3_point1":"Quiz nature personnalisables","feature3_point2":"Scénarios d\'aventure textuels","feature3_point3":"Défis spécifiques aux espèces","feature4_title":"Accès Complet Hors Ligne","feature4_desc":"Accédez à toutes les fonctionnalités essentielles sans connexion internet. Notre mode hors ligne inclut l\'identification des espèces, des cartes détaillées, des guides de la faune et des outils de navigation - parfait pour les aventures reculées.","feature4_point1":"Fonctionnalité complète hors ligne","feature4_point2":"Données régionales téléchargeables","feature4_point3":"Guides des espèces hors ligne","feature5_title":"Guide Nature IA","feature5_desc":"Obtenez des conseils personnalisés de notre expert nature IA. Posez des questions sur la faune locale, recevez des conseils spécifiques aux espèces et apprenez sur les écosystèmes par conversation naturelle.","feature5_point1":"Assistant nature IA 24/7","feature5_point2":"Informations contextuelles sur la faune","feature5_point3":"Parcours d\'apprentissage personnalisés","feature6_title":"Communauté Mondiale de la Faune","feature6_desc":"Connectez-vous avec des passionnés de nature du monde entier. Partagez vos observations de la faune, découvrez de nouveaux endroits et contribuez à notre base de données croissante d\'observations d\'espèces.","feature6_point1":"Partagez vos rencontres avec la faune","feature6_point2":"Découvrez les points d\'intérêt","feature6_point3":"Défis communautaires"},"CallToAction":{"title":"Ne Manquez Plus Aucun Moment Incroyable avec la Faune !","subtitle":"Rejoignez des milliers de passionnés de nature qui découvrent et identifient déjà la faune comme jamais auparavant. Téléchargez Wildscope maintenant et transformez vos aventures en plein air !","appstore":"Télécharger sur l\'App Store","playstore":"Obtenir sur Google Play","button":"Commencez Votre Voyage Sauvage","playstoreLink":"https://play.google.com/store/apps/details?id=com.duselk.theoutdoorbible","benefits":["✓ Identification Instantanée des Plantes & Animaux","✓ Fonctionne Hors Ligne en Zones Reculées","✓ Navigation & Suivi GPS","✓ Guide Nature Alimenté par l\'IA","✓ Communauté Mondiale de la Faune"]},"Footer":{"copyright":"© {year} Wildscope. Tous droits réservés.","impressum":"Mentions Légales","privacy":"Politique de Confidentialité","contact":"Contact"},"CookieBanner":{"message":"Ce site web utilise des cookies pour vous garantir la meilleure expérience sur notre site.","accept":"Accepter","decline":"Refuser"},"ImpressumPage":{"title":"Mentions Légales","section1_title":"Information selon § 5 TMG (loi allemande)","address":"Dustin Keßler<br />Kurt Schumacher Straße 93<br />46539 Dinslaken<br />Allemagne","contact_title":"Contact","contact_email":"E-mail: ","responsibility_title":"Responsable du contenu selon § 55 para. 2 RStV (loi allemande)","disclaimer_title":"Clause de non-responsabilité","disclaimer_text":"Le contenu de notre site a été créé avec le plus grand soin. Cependant, nous ne pouvons garantir l\'exactitude, l\'exhaustivité et l\'actualité du contenu. En tant que fournisseur de services, nous sommes responsables de notre propre contenu sur ces pages selon les lois générales conformément au § 7 para. 1 TMG (loi allemande). Selon les §§ 8 à 10 TMG (loi allemande), en tant que fournisseur de services, nous ne sommes pas tenus de surveiller les informations transmises ou stockées par des tiers, ni d\'enquêter sur des circonstances qui indiquent une activité illégale."},"PrivacyPage":{"title":"Politique de Confidentialité","overview_title":"Politique de Confidentialité pour Outdoor-Bible","last_updated":"Dernière mise à jour: 06.02.2025","responsible_party_title":"1. Responsable","responsible_party_info":"Dustin Keßler\\nAdresse: Speldorfer Straße 16, 46049 Oberhausen\\nE-mail: duselkay@gmail.com","data_collection_title":"2. Quelles données collectons-nous?","data_collection_intro":"La plupart des données sont stockées localement sur votre appareil. Les données ne sont stockées dans le cloud ou des services externes que lorsque vous utilisez des fonctionnalités spécifiques.","location_data_title":"📍 Données de localisation","location_data_info":"• Le traitement a lieu localement sur votre appareil, pas de stockage permanent\\n• Les données de localisation ne sont envoyées à des services externes que lorsque certaines fonctionnalités sont utilisées:\\n  - Google Places et OpenStreetMap (OSM): Autocomplétion et recherche de POI\\n  - GBIF: Requête d\'animaux et plantes dans votre région\\n  - OpenWeather: Données météorologiques basées sur votre localisation\\n  - OpenElevation: Informations d\'altitude pour l\'analyse du terrain\\n  - Google Gemini et OpenAI: Si vous utilisez des fonctionnalités IA (ex., quiz, mode aventure)","firebase_title":"💾 Firebase pour le stockage et l\'authentification","firebase_info":"• Nous utilisons Firebase pour l\'authentification des utilisateurs et le stockage des données\\n• Des données telles que les comptes utilisateurs, les publications, les commentaires et les téléchargements sont stockées dans Firebase\\n• Firebase met en œuvre ses propres contrôles de sécurité et d\'accès pour protéger vos données","analytics_title":"📊 PostHog Analytics et utilisation de l\'application","analytics_info":"• Nous utilisons PostHog pour des statistiques d\'utilisation anonymisées\\n• PostHog nous aide à comprendre et améliorer l\'utilisation de l\'application\\n• Les données collectées incluent: écrans visités, interactions avec l\'application, durée de session\\n• Aucune donnée personnelle n\'est liée à votre compte\\n• Vous pouvez désactiver le suivi à tout moment dans les paramètres","account_data_title":"👤 Compte utilisateur et données de profil","account_data_info":"• Inscription requise\\n• Stockage de: nom d\'utilisateur, adresse e-mail, statut premium\\n• Les mots de passe sont stockés de manière cryptée","uploads_title":"📤 Téléchargements et interactions","uploads_info":"Les données ne sont stockées dans le cloud que lorsque vous:\\n• Partagez une image ou une vidéo: Nom d\'utilisateur, date et lieu de capture\\n• Créez une publication: Le texte est stocké, mais pas votre localisation\\n• Aimez ou commentez: Seule l\'interaction elle-même est stockée","external_content_title":"🎥 Vidéos YouTube et contenu Wikimedia","external_content_info":"• Du contenu externe est intégré\\n• Ces services utilisent leurs propres technologies de suivi","data_processing_title":"3. Pourquoi traitons-nous vos données?","data_processing_info":"Bases légales selon le RGPD:\\n• Art. 6(1)(a) (Consentement): Partage de localisation, utilisation d\'IA, téléchargements\\n• Art. 6(1)(b) (Exécution contractuelle): Compte utilisateur et adhésion premium\\n• Art. 6(1)(f) (Intérêt légitime): Amélioration de l\'application via PostHog analytics","data_storage_title":"4. Stockage et suppression des données","data_storage_info":"Où sont stockées vos données?\\n• Données de localisation: Local, non stockées de façon permanente\\n• Publications, j\'aime, téléchargements: Dans Firebase, si activement partagés\\n• Données analytiques: Anonymisées via PostHog\\n• La plupart des données d\'application sont stockées localement sur votre appareil\\n\\nSuppression des données:\\n• Toutes les données peuvent être supprimées dans les paramètres de l\'application\\n• La suppression du compte supprime toutes les données liées dans Firebase","data_access_title":"5. Qui a accès à vos données?","data_access_info":"• Pas de partage à des fins publicitaires\\n• Les données de localisation ne sont envoyées que temporairement à des services externes\\n• YouTube et Wikimedia collectent leurs propres données lors de l\'utilisation\\n• PostHog traite des statistiques d\'utilisation anonymes\\n• Les API Google sont utilisées pour diverses fonctions\\n• Pas de stockage des données de paiement (Google Play / Apple Pay)","gdpr_rights_title":"6. Vos droits selon le RGPD","gdpr_rights_info":"• Information sur les données stockées\\n• Correction des données incorrectes\\n• Suppression de vos données\\n• Portabilité des données\\n• Retrait du consentement à tout moment\\n\\n📧 Contact pour les questions de confidentialité: duselkay@gmail.com","viewOnWebsite":"Voir sur le site web"},"TermsPage":{"title":"Conditions d\'Utilisation","updated":"Dernière mise à jour: 06.02.2025","general_title":"1. Généralités","general_text":"Ces conditions d\'utilisation régissent l\'utilisation de l\'application Wildscope. En créant un compte, vous acceptez ces conditions. L\'âge minimum d\'utilisation est de 16 ans. L\'application fournit des fonctionnalités de suivi de la faune, d\'identification des plantes et d\'exploration de la nature conçues pour améliorer votre expérience en plein air.","features_title":"2. Fonctionnalités de l\'Application","features_text":"Wildscope fournit des données basées sur la localisation pour les animaux, les plantes, les points d\'intérêt et les informations météorologiques. L\'application comprend des fonctionnalités alimentées par l\'IA telles que des quiz sur la nature et le mode aventure, la possibilité de télécharger des photos et vidéos, créer des publications, et accéder aux fonctionnalités premium pour du contenu supplémentaire et des fonctionnalités améliorées.","account_title":"3. Compte Utilisateur & Responsabilité","account_text1":"Vous êtes responsable du maintien de la sécurité de votre compte et de l\'utilisation d\'un mot de passe sécurisé. Les utilisateurs doivent se conformer à toutes les lois et réglementations applicables lors de l\'utilisation de l\'application.","prohibited_subtitle":"Contenu Interdit","prohibited_text":"Il est interdit aux utilisateurs de publier du contenu illégal, offensant ou protégé par des droits d\'auteur. La manipulation des données de localisation est strictement interdite. La suppression du compte est disponible à tout moment via les paramètres de l\'application.","data_title":"4. Gestion Technique des Données","data_text":"La plupart des données sont stockées localement sur votre appareil pour une performance optimale et la confidentialité. Firebase est utilisé pour l\'authentification et le stockage cloud lorsque nécessaire. PostHog fournit des analyses d\'utilisation anonymisées pour améliorer l\'application. Les API Google permettent diverses fonctions de l\'application. Nous n\'utilisons pas vos données à des fins publicitaires.","premium_title":"5. Adhésion Premium","premium_text":"Les fonctionnalités premium sont disponibles via Google Play ou Apple Pay. Il n\'y a pas de droit de rétractation après utilisation des fonctionnalités premium. Les abonnements premium peuvent être annulés à tout moment via votre magasin d\'applications respectif.","disclaimer_title":"6. Clause de Non-Responsabilité","disclaimer_subtitle":"Limitation de Responsabilité","disclaimer_text":"Nous n\'assumons aucune responsabilité pour les informations incorrectes sur les plantes, animaux ou points d\'intérêt; les dommages résultant d\'une application incorrecte des conseils de survie; la perte de données ou les dysfonctionnements de l\'application; ou les problèmes de sécurité des données. Bien que nous mettions en place des mesures de sécurité élevées, nous ne pouvons garantir une sécurité des données à 100%.","content_title":"7. Droits sur le Contenu","uploads_subtitle":"Contenu Généré par l\'Utilisateur","uploads_text":"Tous les téléchargements et contenus générés par l\'utilisateur restent la propriété de l\'utilisateur. Le contenu est privé par défaut sauf s\'il est explicitement partagé. Le contenu illégal sera supprimé sans préavis.","app_content_subtitle":"Contenu de l\'Application & Droits d\'Auteur","app_content_text":"Tout le contenu de l\'application, y compris les données, textes et graphiques, est protégé par des droits d\'auteur. L\'utilisation commerciale du contenu de l\'application est strictement interdite sans autorisation écrite.","changes_title":"8. Modifications des Conditions d\'Utilisation","changes_text":"L\'utilisation continue de l\'application après modification de ces conditions implique l\'acceptation des nouvelles conditions. Les utilisateurs seront notifiés des modifications importantes via l\'application ou par e-mail.","contact_info":"Pour le support et les demandes, contactez-nous à: duselkay@gmail.com"},"ContactPage":{"title":"Contact","contact_intro":"N\'hésitez pas à nous contacter pour toute question, commentaire ou demande.","contact_person":"Personne à contacter","country":"Allemagne"},"NotFound":{"title":"Page Non Trouvée","description":"Désolé, la page que vous recherchez n\'existe pas ou a été déplacée.","backHome":"Retour à la Page d\'Accueil"},"General":{"loading":"Chargement...","comingSoon":"Bientôt disponible"},"FAQ":{"title":"Questions Fréquemment Posées sur le Suivi de la Faune","question1":"Comment Wildscope se compare-t-il à d\'autres applications d\'identification de la nature comme iNaturalist?","answer1":"Alors qu\'iNaturalist se concentre principalement sur l\'identification des espèces et la science citoyenne, Wildscope offre une expérience en plein air complète avec des fonctionnalités supplémentaires spécifiquement conçues pour les amoureux de la nature. Notre application comprend l\'identification de la faune hors ligne, des outils de navigation GPS pour l\'exploration en pleine nature, l\'apprentissage interactif à travers des quiz sur la nature, et un compagnon IA qui comprend votre environnement pour fournir des conseils personnalisés—ce qui la rend parfaite tant pour les amateurs occasionnels de nature que pour les traqueurs sérieux de la faune.","question2":"Puis-je identifier des plantes et des animaux hors ligne avec Wildscope?","answer2":"Partiellement. L\'analyse par IA nécessite une connexion Internet, mais vous verrez toutes les espèces suivies de votre région affichées et pourrez les utiliser pour faciliter l\'identification.","question3":"Quels appareils prennent en charge l\'application d\'exploration de la nature Wildscope?","answer3":"Les fonctionnalités de suivi de la faune et d\'identification de la nature de Wildscope sont disponibles à la fois pour les appareils iOS (iPhone/iPad) et Android via l\'App Store et le Google Play Store, ce qui la rend accessible pour pratiquement tous les utilisateurs de smartphones.","question4":"L\'application d\'identification de la faune Wildscope est-elle gratuite?","answer4":"Wildscope offre une version gratuite avec des fonctionnalités essentielles d\'identification de la faune et d\'exploration de la nature. Notre abonnement premium débloque des capacités avancées comme des trouvailles d\'espèces illimitées, plus de crédits, plus de lieux personnalisés à visiter, et des avantages supplémentaires. Consultez l\'application pour connaître les options d\'abonnement actuelles.","question5":"Quelle est la précision de l\'identification des plantes et des animaux de Wildscope?","answer5":"Wildscope combine des données de localisation avec une technologie IA avancée pour identifier la faune et les plantes avec une grande précision. Bien que notre système de reconnaissance s\'améliore continuellement, la précision d\'identification varie selon l\'espèce, la qualité de l\'image et l\'angle de vision. Nous améliorons constamment nos algorithmes grâce à des mises à jour régulières pour fournir une identification de plus en plus précise de la faune et des plantes dans tous les environnements.","question6":"Puis-je contribuer à la base de données de la faune de Wildscope?","answer6":"Absolument! Wildscope prospère grâce aux contributions de la communauté. Vos observations de la faune et identifications de plantes sont ajoutées en toute sécurité à notre base de données d\'écosystème, améliorant la précision de l\'application pour tous. Cette approche collaborative crée une ressource complète d\'identification de la faune qui bénéficie à tous les amoureux de la nature.","question7":"Wildscope est-il développé par une grande entreprise technologique?","answer7":"Non, Wildscope est un projet indépendant développé par un passionné de nature dévoué. L\'application est conçue et maintenue par un seul développeur passionné qui privilégie la précision et l\'expérience utilisateur plutôt que la monétisation. Cette approche indépendante garantit que Wildscope reste fidèle à sa mission fondamentale: aider les gens à se connecter et à comprendre la nature sans compromettre la confidentialité ou l\'expérience de l\'utilisateur."},"Audience":{"title":"À Qui s\'Adresse Wildscope ?","intro":"Que vous soyez un explorateur chevronné ou que vous commenciez tout juste votre voyage dans la nature, Wildscope est conçu pour vous :","audience1_title":"Randonneurs & Trekkeurs","audience1_desc":"Naviguez sur les sentiers, identifiez les espèces et restez en sécurité avec des cartes hors ligne et des outils de survie.","audience2_title":"Photographes Animaliers & Ornithologues","audience2_desc":"Découvrez, suivez et identifiez les espèces insaisissables pour capturer la photo parfaite.","audience3_title":"Familles & Explorateurs Occasionnels","audience3_desc":"Transformez les visites de parcs en aventures d\'apprentissage passionnantes pour tous les âges.","audience4_title":"Éducateurs & Étudiants","audience4_desc":"Un outil puissant pour l\'éducation en plein air, les projets de biodiversité et les études naturalistes.","audience5_title":"Survivalistes & Adeptes du Bushcraft","audience5_desc":"Perfectionnez vos compétences avec l\'identification des plantes, les guides de construction d\'abris et les ressources hors ligne.","conclusion":"Et toute personne curieuse du monde naturel !"},"Testimonials":{"title":"Ce que disent nos Explorateurs","testimonial1":"Wildscope a complètement changé ma façon d\'explorer. Les cartes hors ligne sont une bouée de sauvetage, et l\'identification par IA est incroyablement précise !","testimonial1_author":"Sarah L.","testimonial1_role":"Passionnée de Randonnée","testimonial2":"En tant que professeur de biologie, cette application est un outil fantastique pour mes étudiants. Elle rend l\'apprentissage de la flore et de la faune locales tellement plus interactif.","testimonial2_author":"David K.","testimonial2_role":"Éducateur"},"Pricing":{"title":"Choisissez Votre Plan Wildscope","free_title":"Explorateur Basique","free_subtitle":"Commencez votre voyage avec les fonctionnalités essentielles.","free_price":"Gratuit","free_price_suffix":"Pour toujours","free_feature1":"Identification IA des espèces (limitée)","free_feature2":"Cartes régionales hors ligne (1 région)","free_feature3":"Accès au guide de survie de base","free_feature4":"Accès au forum communautaire","free_feature5":"Suivre 5 POI favoris","free_feature_limited1":"Expérience avec publicité","free_cta":"Inclus avec le téléchargement","pro_badge":"Meilleur Prix","pro_title":"Wildscope Pro","pro_subtitle":"Libérez toute la puissance de l\'exploration de la nature.","pro_price":"2,99 €","pro_price_suffix":"par mois (ou 17,99 €/an)","pro_feature1":"Identification IA illimitée des espèces","pro_feature2":"Cartes régionales hors ligne illimitées","pro_feature3":"Guide de survie complet & outils avancés","pro_feature4":"Fonctionnalités communautaires Premium","pro_feature5":"Suivre un nombre illimité de POI favoris","pro_feature6":"Expérience sans publicité","pro_feature7":"Support prioritaire","pro_cta":"Passez Pro & Explorez Plus","footnote":"Les prix peuvent varier selon la région. Abonnements gérés via l\'App Store/Google Play."}}');

